import {
  componentAttrs,
  mergeDefaultModifiers,
} from "../_utils/component.helper";
import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";

function resolveLink(link) {
  if (!link) return null;
  if (typeof link === "string") return { url: link, target: "_self" };
  if (typeof link === "object" && link.url)
    return { url: link.url, target: link.target || "_self" };
  return null;
}

/**
 * Font Awesome classic/thin, per this project's icon convention -- not an
 * inline SVG. Matches the reference implementation's own icon exactly
 * (Icon name="right-from-bracket"), which wasn't achievable when this was
 * first built (no Font Awesome kit wired up at the time).
 */
const ICON_SVG =
  '<i class="fa-light fa-right-from-bracket" aria-hidden="true"></i>';

export default {
  async main(input, info) {
    const { Quick_Exit: quickExit = {} } = input;

    const {
      label = "Quick exit",
      message = "Click anywhere in this banner to exit. Call 000 if you're in immediate danger.",
      exitUrl = "https://www.google.com",
      whatIsThisHref = null,
      ariaLabel = "",
    } = quickExit;

    const {
      QUICK_EXIT_INSERT_TARGET = '[data-component=global-alerts]',
      QUICK_EXIT_INSERT_POSITION = 'afterend'
    } = info?.env ?? {};
    const injectArgs = [QUICK_EXIT_INSERT_POSITION, QUICK_EXIT_INSERT_TARGET];
    const resolvedExit = resolveLink(exitUrl) || {
      url: "https://www.google.com",
      target: "_self",
    };
    const resolvedWhatIsThis = resolveLink(whatIsThisHref);

    const regionLabel = ariaLabel || label;

    const whatIsThisHtml = resolvedWhatIsThis
      ? `<a class="quick-exit__link mono" href="${escURL(resolvedWhatIsThis.url)}"${resolvedWhatIsThis.target !== "_self" ? ` target="${escHTML(resolvedWhatIsThis.target)}" rel="noopener noreferrer"` : ""}>What is this?</a>`
      : "";

    return /*html*/ `
<div ${componentAttrs("quick-exit", mergeDefaultModifiers(input, ['fullwidth background']))} role="region" aria-label="${escHTML(regionLabel)}" data-inject="${injectArgs}">
  <button type="button" class="quick-exit__action" data-quick-exit-url="${escURL(resolvedExit.url)}">
    <div class="quick-exit__heading">
      <span class="quick-exit__icon" aria-hidden="true">${ICON_SVG}</span>
      <span class="quick-exit__title" data-sq-field="label">${escHTML(label)}</span>
    </div>
    <p class="quick-exit__message" data-sq-field="message">${escHTML(message)}</p>
  </button>
  ${whatIsThisHtml}
</div>
`;
  },
};
